-- Finished runs (death or victory). run_id is generated by the client: resending is idempotent.
CREATE TABLE runs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  hero_class TEXT NOT NULL,
  result TEXT NOT NULL CHECK (result IN ('victory', 'defeat')),
  chapter INTEGER NOT NULL,
  floor INTEGER NOT NULL,
  turns INTEGER NOT NULL,
  seed INTEGER NOT NULL,
  game_version TEXT NOT NULL,
  stats TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_runs_user ON runs (user_id, created_at);
CREATE INDEX idx_runs_leaderboard ON runs (hero_class, result, chapter, floor, turns);
